String";s:522:"/**
	 * Execute the expiration check
	 *
	 * Fetches all active signing requests and marks those past their deadline
	 * as EXPIRED.
	 *
	 * @param mixed $argument Job arguments. The job is registered as a bare
	 *                        TimedJob and takes no arguments, so this is
	 *                        normally null; it is echoed into the start log so
	 *                        an unexpected payload is visible to operators.
	 *
	 * @return void
	 *
	 * @spec openspec/changes/document-signing/tasks.md#task-1
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:24:"OCA\Filinq\BackgroundJob";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:10:{s:17:"datetimeimmutable";s:17:"DateTimeImmutable";s:17:"datetimeinterface";s:17:"DateTimeInterface";s:9:"exception";s:9:"Exception";s:15:"settingsservice";s:34:"OCA\Filinq\Service\SettingsService";s:19:"signingauditservice";s:38:"OCA\Filinq\Service\SigningAuditService";s:14:"signingservice";s:33:"OCA\Filinq\Service\SigningService";s:12:"itimefactory";s:37:"OCP\AppFramework\Utility\ITimeFactory";s:8:"timedjob";s:26:"OCP\BackgroundJob\TimedJob";s:10:"iappconfig";s:14:"OCP\IAppConfig";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:0;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:4:"void";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:8:"argument";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"mixed";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency