	 *
	 * @no-admin-idor-exempt ownership is enforced one layer down.
	 * Every path here loads the batch through BatchStateService::getBatch(),
	 * which compares the record's userId against the session user and returns
	 * null for a mismatch (admins excepted for support). It returns null
	 * rather than throwing precisely so a denied read is indistinguishable
	 * from a missing one — both answer 404 — so a caller cannot even confirm
	 * another user's batch exists.
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:21:"OCA\Filinq\Controller";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:20:{s:21:"batchanonymizeservice";s:40:"OCA\Filinq\Service\BatchAnonymizeService";s:22:"batchextractionservice";s:41:"OCA\Filinq\Service\BatchExtractionService";s:18:"batchreportservice";s:37:"OCA\Filinq\Service\BatchReportService";s:19:"batchrequestservice";s:38:"OCA\Filinq\Service\BatchRequestService";s:17:"batchstateservice";s:36:"OCA\Filinq\Service\BatchStateService";s:18:"batchuploadservice";s:37:"OCA\Filinq\Service\BatchUploadService";s:26:"entityconsolidationservice";s:45:"OCA\Filinq\Service\EntityConsolidationService";s:18:"folderbatchservice";s:37:"OCA\Filinq\Service\FolderBatchService";s:17:"wooprofileservice";s:36:"OCA\Filinq\Service\WooProfileService";s:11:"filinqadmin";s:31:"OCA\Filinq\Settings\FilinqAdmin";s:10:"controller";s:27:"OCP\AppFramework\Controller";s:4:"http";s:21:"OCP\AppFramework\Http";s:22:"authorizedadminsetting";s:54:"OCP\AppFramework\Http\Attribute\AuthorizedAdminSetting";s:20:"datadownloadresponse";s:42:"OCP\AppFramework\Http\DataDownloadResponse";s:12:"jsonresponse";s:34:"OCP\AppFramework\Http\JSONResponse";s:10:"iappconfig";s:14:"OCP\IAppConfig";s:5:"il10n";s:9:"OCP\IL10N";s:8:"irequest";s:12:"OCP\IRequest";s:12:"iusersession";s:16:"OCP\IUserSession";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:34:"O