	 * Whether a column list is shaped like an OpenRegister shard table.
	 *
	 * `_uuid` is the identity every step of the move is keyed on and `_register`
	 * is the column the move exists to rewrite. A table missing either is not
	 * one of ours whatever its name says, and this step must not write to it.
	 *
	 * @param array<int, string> $columns The column list to check.
	 *
	 * @return bool True when both required columns are present.
	 *
	 * @spec exclude No canonical spec covers the consolidation of Filinq's five
	 *  OpenRegister registers into one. Pointing this at an existing spec would
	 *  report conformance to a requirement that says nothing about it.
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:17:"OCA\Filinq\Repair";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:4:"bool";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:7:"columns";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"array";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀attributes";a:0:{}}i:7;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:14:"partitionUuids";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1082:"/**
	 * Split the source uuids into the ones that may move and the ones that may not.
	 *
	 * A uuid already present in the target is a CONFLICT, and this step refuses
	 * it rather than resolving it. Two objects sharing a uuid across the two
	 * tables can mean a previous run inserted and then failed to delete, or it
	 * can mean two genuinely different objects that were assigned the same
	 * identity. Those want opposite treatments and nothing available here tells
	 * them apart, so both rows are left exactly where they are and the conflict
	 * is logged. Merging is a decision about data, not a migration.
	 *
	 * @param array<int, string> $sourceUuids Uuids in the source table.
	 * @param array<int, string> $targetUuids Uuids already in the target table.
	 *
	 * @return array{movable: array<int, string>, conflicts: array<int, string>}
	 *
	 * @spec exclude No canonical spec covers the consolidation of Filinq's five
	 *  OpenRegister registers into one. Pointing this at an existing spec would
	 *  report conformance to a requirement that says nothing about it.
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:17:"OCA\Filinq\Repair";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:5:"array";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:2:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:11:"sourceUuids";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"array";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:11:"targetUuids";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"array";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀attributes";a:0:{}}i:8;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:5:"chunk";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:444:"/**
