tionLink";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1315:"/**
	 * Persist or update the mapping between a source file and its anonymised counterpart.
	 *
	 * Idempotent UPSERT keyed on `sourceFileId`: the first successful
	 * anonymisation of a file creates an `anonymizationLink` object in the
	 * `document` register; every subsequent re-anonymisation of the same
	 * source file updates that same record (preserving its `@self`, which
	 * triggers OpenRegister's update path) and increments `runCount`. Both
	 * `sourceFileId` and `anonymizedFileId` are facetable on the schema so
	 * OR's search API resolves the link in both directions.
	 *
	 * Best-effort: the anonymised file already exists and the run has
	 * succeeded, so a persistence failure here MUST NOT abort or alter the
	 * response. Failures are caught, logged at warning level, and the
	 * unmodified `$resultInfo` is returned (without an `anonymizationLinkId`
	 * key).
	 *
	 * @param int $fileId The source (unanonymised) Nextcloud file ID.
	 * @param mixed $sourceNode The source file node (used for name/path/owner metadata).
	 * @param array<string, mixed> $resultInfo Current result; carries anonymizedFileId/Name/Path + replacementCount.
	 *
	 * @return array<string, mixed> The `$resultInfo`, enriched with `anonymizationLinkId` on success.
	 *
	 * @spec openspec/specs/anonymization/spec.md
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:3:{s:9:"exception";s:9:"Exception";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";s:9:"throwable";s:9:"Throwable";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:5:"array";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:3:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:6:"fileId";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:3:"int";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:10:"sourceNode";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"mixed";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"