	 * @var string
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:1:{s:14:"errorexception";s:14:"ErrorException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}}i:1;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:21:"MODE_CASE_INSENSITIVE";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:17:"'caseInsensitive'";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:71:"/**
	 * Case-insensitive match mode (default).
	 *
	 * @var string
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:1:{s:14:"errorexception";s:14:"ErrorException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}}i:2;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:18:"MODE_WORD_BOUNDARY";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:14:"'wordBoundary'";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:86:"/**
	 * Case-insensitive, word-boundary-delimited match mode.
	 *
	 * @var string
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:1:{s:14:"errorexception";s:14:"ErrorException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}}i:3;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:5:"match";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1541:"/**
	 * Find every occurrence of every (non-blank) term in `$text`.
	 *
	 * `$terms` rows carry `value` (the needle) and an optional `label`
	 * (falls back to the term's own value when absent — the dictionary-level
	 * default-label fallback is the caller's responsibility per design.md
	 * §D2, so this method never has to resolve a dictionary label itself).
	 *
	 * Overlap handling: terms are processed longest-value-first so a shorter
	 * term cannot pre-empt a longer one at an overlapping position (mirrors
	 * OpenRegister's redaction longest-needle rule). Once a position range is
	 * claimed by a match it is never claimed again by a shorter term's match.
	 * The `fuzzy` flag is accepted-and-ignored — no approximate matching in
	 * this version (design.md Open Questions).
	 *
	 * Occurrences are returned in document order. Each `value` is the literal
	 * substring found at that position, which may differ in case from the
	 * declared term under `caseInsensitive`/`wordBoundary`.
	 *
	 * @param string $text The document text to search.
	 * @param array<int, array{value: string, label?: string}> $terms Candidate terms.
	 * @param string $mode One of {@see VALID_MODES}; an
	 *                     unrecognised value is treated
	 *                     as {@see
	 *                     MODE_CASE_INSENSITIVE}.
	 *
	 * @return array<int, array{value: string, label: string, positionStart: int, positionEnd: int}>
