	 *
	 * @SuppressWarnings(PHPMD.ExcessiveMethodLength) The plain-language rendition
	 * step pushed this past the threshold. It belongs in the same method because
	 * the formal document and its plain counterpart are filed together or not at
	 * all; splitting the step out would make a half-filed pair reachable.
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:5:{s:9:"exception";s:9:"Exception";s:16:"batchdocumentjob";s:41:"OCA\Filinq\BackgroundJob\BatchDocumentJob";s:8:"ijoblist";s:26:"OCP\BackgroundJob\IJobList";s:18:"containerinterface";s:32:"Psr\Container\ContainerInterface";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:5:"array";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:3:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:10:"templateId";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:6:"string";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:8:"dataRefs";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5: