	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:26:"OCA\Filinq\Service\Editing";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:7:{s:29:"documentobjectserviceresolver";s:48:"OCA\Filinq\Service\DocumentObjectServiceResolver";s:20:"finaldocumentservice";s:39:"OCA\Filinq\Service\FinalDocumentService";s:21:"doesnotexistexception";s:41:"OCP\AppFramework\Db\DoesNotExistException";s:4:"file";s:14:"OCP\Files\File";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";s:9:"throwable";s:9:"Throwable";s:10:"ziparchive";s:10:"ZipArchive";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:7:"?string";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:4:"file";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:14:"OCP\Files\File";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀attributes";a:0:{}}i:3;