	 * Read the anchored blocks of a package.
	 *
	 * Anchors are derived from block CONTENT, not from position: a human
	 * inserting a paragraph shifts every index, and an index-addressed edit
	 * would then land in the wrong place with no error. They are recomputed on
	 * every read, so an anchor is only valid for as long as the block's text is
	 * unchanged -- which is the property that makes a stale edit fail loudly.
	 *
	 * @param string $packageBytes The raw package bytes.
	 * @param string $extension The file extension, without a leading dot.
	 *
	 * @return array{format: string, blocks: array<int, array{anchor: string, text: string}>}
	 *
	 * @throws RuntimeException When the extension is unsupported or the package is unreadable.
	 *
	 * @spec openspec/specs/document-editing/spec.md#requirement-edits-address-stable-anchors-never-positional-indexes
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:26:"OCA\Filinq\Service\Editing";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:1:{s:16:"runtimeexception";s:16:"RuntimeException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:5:"array";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:2:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:12:"packageBytes";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:6:"string";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:9:"extension";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:6:"string";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNod