	 * @spec openspec/specs/anonymization/spec.md
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:3:{s:25:"conversionfailedexception";s:46:"OCA\Filinq\Exception\ConversionFailedException";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";s:9:"throwable";s:9:"Throwable";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:5:"array";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:6:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:6:"fileId";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:3:"int";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:4:"node";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"mixed";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\Exporte