	 * Resolve listRefs (collection references) into arrays of objects.
	 *
	 * Every listRef is validated up front (fail-fast) before any
	 * OpenRegister search runs, so a malformed listRef never triggers a
	 * partial lookup. Once validated, each listRef is resolved
	 * independently; a search failure for one listRef does not abort the
	 * others and is instead collected as a soft error (mirroring dataRefs
	 * in DataResolverService::resolve()).
	 *
	 * @param array $listRefs Array of collection references, each with
	 *                        'register', 'schema' and optional
	 *                        'filter', 'limit', 'order', 'as' keys
	 * @param array $reservedKeys Context keys already used by dataRefs; a
	 *                            listRef's 'as' key must not collide with
	 *                            these
	 *
	 * @return array{data: array<string, array>, errors: array} Resolved
	 *                                                          lists keyed by 'as', and any per-item resolution errors
	 *
	 * @throws Exception If a listRef violates a request-level guardrail
	 *                   (too many entries, invalid filter values, invalid
	 *                   or colliding 'as' key) — all HTTP 400
	 *
	 * @spec openspec/changes/document-generation-list-refs/specs/document-creatie-sjablonen/spec.md
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:4:{s:9:"exception";s:9:"Exception";s:11:"iappmanager";s:19:"OCP\App\IAppManager";s:18:"containerinterface";s:32:"Psr\Container\ContainerInterface";s:16:"runtimeexception";s:16:"RuntimeException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:5:"array";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:2:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:8:"listRefs";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"array";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:12:"reservedKeys";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"array";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s