	 *
	 * @spec openspec/changes/digital-signing-integration/tasks.md#2-2
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:26:"OCA\Filinq\Service\Signing";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:7:{s:17:"datetimeimmutable";s:17:"DateTimeImmutable";s:17:"datetimeinterface";s:17:"DateTimeInterface";s:15:"settingsservice";s:34:"OCA\Filinq\Service\SettingsService";s:10:"iappconfig";s:14:"OCP\IAppConfig";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";s:16:"runtimeexception";s:16:"RuntimeException";s:9:"throwable";s:9:"Throwable";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:4:"bool";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:5:"level";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:6:"string";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀attributes";a:0:{}}i:9;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:21:"produceSignedArtifact";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:2603:"/**
	 * Produce a verifiable, identity-bound native SES signed artifact (v2).
	 *
	 * Embeds a `/DocuDesk-Signature(base64-json)` marker binding the signer
	 * identity, timestamp, level, method and IP. The assertion carries a
	 * version discriminator `v: 2` and a MAC computed as
	 * `HMAC-SHA256(secret, sha256(canonical-document) . "\n" .
	 * canonical-JSON(assertion-minus-mac))` — the identity fields are now
	 * INSIDE the MAC input, so rewriting any of them (signer name, level,
	 * timestamp, method) while keeping the original `mac` fails verification
	 * (signing-trust-rebuild REQ-DDSTR-001, closing the #284 residual where
	 * the v1 MAC covered only the content-hash and left every assertion
	 * field forgeable). `SigningVerificationService::verifyAssertion()`
	 * recomputes the identical value and validates the artifact.
	 *
	 * When the completing act is portal-originated (`portal-signing-actions` /
	 * `portal-signing-surface`), the receiver-resolved portal subject claims
	 * (`portalSubjectRef`, `portalIdentityRef`, `portalTrust`, `portalJti`) are
	 * threaded in via `$context` and folded into the SAME assertion — and
	 * therefore the SAME MAC — before it is computed, so the portal signer's
	 * identity is cryptographically bound too (portal-signing-surface
	 * REQ-DDPSS-004, closing the portaliq#3 forgeable-signer class for the
	 * portal seam). Those fields are present only when the caller (always
	 * `SigningService`, sourced only from the verified assertion — never
	 * client input) supplies them.
	 *
	 * Honest-completion gates: (1) an unset signing secret and (2) a
	 * requested level this provider does not support (`supportsLevel()`,
	 * REQ-DDSTR-002 point 3, defence in depth alongside the request-creation
	 * and completion-resolution gates in `SigningService`) both throw rather
	 * than emit an unverifiable or mislabelled artifact.
	 *
	 * @param string $documentContent The original document bytes.
	 * @param array<string, mixed> $context Signing context: signer,
	 *                                      signers, timestamp, ip,
	 *                                      level, and optionally the
	 *                                      portal* identity claims.
	 *
	 * @return string The signed document bytes.
	 *
	 * @throws RuntimeException When the signing secret is unset or the
	 *                          requested level is not SES.
	 *
	 * @spec openspec/specs/document-signing/spec.md
	 * @spec openspec/specs/portal-signing-surface/spec.md
	 * @spec openspec/changes/signer-identity-rails/specs/signer-identity-rails/spec.md
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:26:"OCA\Filinq\Service\Signing";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:7:{s:17:"datetimeimmutable";s:17:"DateTimeImmutable";s:17:"datetimeinterface";s:17:"DateTimeInterface";s:15:"settingsservice";s:34:"OCA\Filinq\Service\SettingsService";s:10:"iappconfig";s:14:"OCP\IAppConfig";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";s:16:"runtimeexception";s:16:"RuntimeException";s:9:"throwable";s:9:"Throwable";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:6:"string";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:2:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:15:"documentContent";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:6:"string";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:7:"context";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:5:"array";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}}s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀attributes";a:0:{}}}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀attributes";a:0:{}}}}11095
a:1:{s:59:"../../../lib/Service/Signing/SigningCancellationService.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:53:"OCA\Filinq\Service\Signing\SigningCancellationService";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1692:"/**
 * The one place a signing request is withdrawn.
 *
 * ## Only the creator, decided 2026-08-16
 *
 * Not an app administrator. Not a holder of write access to the document.
 *
 * Write permission on a file is not authority to withdraw a legal process from
 * every signatory. The two coincide often, which is exactly what makes the
 * conflation easy and wrong. An administrator administers an application; they are
 * not a party to an agreement between a requester and its signatories.
 *
 * **The accepted consequence:** a creator who has left the organisation
 * permanently blocks cancellation of their requests. There is no in-app override,
 * deliberately. The refusal names the creator so a blocked user knows who to ask
 * rather than concluding the feature is broken. An "absent creator" escape hatch is
 * a separate change with its own authorisation argument — adding one here on
 * operational grounds is how the administrator path returns through the back door.
 *
 * ## Order of checks is load-bearing
 *
 * Authorisation runs before the provider is contacted (so no partial cancellation)
 * AND before the request id is resolved — otherwise an unauthorised caller could
 * distinguish "no such request" from "not allowed" and enumerate valid ids from the
 * error text.
 *
 * @category Service
 * @package  OCA\Filinq\Service\Signing
 *
 * @author    Conduction Development Team <info@conduction.nl>
 * @copyright 2026 Conduction B.V.
 * @license   EUPL-1.2 https://joinup.ec.europa.eu/collection/eupl/eupl-text-eupl-12
 *
 * @version GIT: <git-id>
 *
 * @link https://filinq.app
 *
 * @spec openspec/changes/signing-cancellation/specs/signing-cancellation/spec.md
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:26:"OCA\Filinq\Service\Signing";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:5:{s:40:"signingcancellationnotsupportedexception";s:61:"OCA\Filinq\Exception\SigningCancellationNotSupportedException";s:14:"signingservice";s:33:"OCA\Filinq\Service\SigningService";s:15:"loggerinterface";s:23:"Psr\Log\LoggerInterface";s:16:"runtimeexception";s:16:"RuntimeException";s:9:"throwable";s:9:"Throwable";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:2:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:236:"/**
	 * Constructor.
	 *
	 * @param SigningProviderFactory $providers Resolves the configured provider.
	 * @param SigningService $requests Signing request lookup.
	 * @param LoggerInterface $logger The logger.
