	 * @param string $action Verb used in the authorisation failure
	 *                       message (`sign` or `decline`).
	 *
	 * @return array<string, mixed> The loaded, authorised signer record.
	 *
	 * @throws RuntimeException When the record is missing, belongs to another
	 *                          request, or the actor is not that signer.
	 *
	 * @spec openspec/specs/portal-signing-actions/spec.md
	 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:18:"OCA\Filinq\Service";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:4:{s:10:"iappconfig";s:14:"OCP\IAppConfig";s:8:"irequest";s:12:"OCP\IRequest";s:12:"iusersession";s:16:"OCP\IUserSession";s:16:"runtimeexception";s:16:"RuntimeException";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";s:5:"array";s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:5:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:9:"requestId";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:6:"string";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀variadic";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀hasDefault";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀attributes";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀phpDoc";N;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀flags";i:0;}i:1;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀name";s:8:"signerId";s:59:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀type";s:6:"string";s:60:"␀PHPStan\Dependency\ExportedNode\ExportedParameterNode␀byRef";b:0;s:63:"␀PHPStan\Dependency\Ex